declare module '*.gltf' { const value:string; export default value; }
declare module '*.glsl' { const value:string; export default value; }
declare module '*.wgsl' { const value:string; export default value; }
declare module '*.css' { const value:Readonly<Record<string,string>>; export default value; }
declare module '*.mp3' { const value:string; export default value; }
declare module '*.wav' { const value:string; export default value; }
declare module '*.ogg' { const value:string; export default value; }
